<template>
  <section class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm dark:border-slate-800 dark:bg-slate-900">
    <div class="flex items-start justify-between gap-3"><div><h3 class="text-sm font-bold text-slate-900 dark:text-white">{{ title }}</h3><p v-if="subtitle" class="mt-1 text-xs text-slate-500 dark:text-slate-400">{{ subtitle }}</p></div><span class="material-icons text-indigo-400">donut_large</span></div>
    <div v-if="total" class="mt-6 flex items-center gap-6"><div class="relative h-36 w-36 shrink-0 rounded-full" :style="donutStyle"><div class="absolute inset-5 flex flex-col items-center justify-center rounded-full bg-white dark:bg-slate-900"><strong class="text-2xl text-slate-900 dark:text-white">{{ total }}</strong><span class="text-[10px] uppercase tracking-wide text-slate-400">negócios</span></div></div><div class="min-w-0 flex-1 space-y-2"><button v-for="item in items" :key="item.label" type="button" class="flex w-full items-center justify-between gap-3 rounded-lg px-2 py-2 text-xs transition hover:bg-slate-50 dark:hover:bg-slate-800" @click="handleSelect(item)"><span class="flex min-w-0 items-center gap-2 truncate text-left text-slate-600 dark:text-slate-300"><i class="h-2.5 w-2.5 shrink-0 rounded-full" :style="{ backgroundColor: item.color }" />{{ item.label }}</span><strong class="text-slate-900 dark:text-white">{{ item.value }}</strong></button><p class="pt-1 text-[11px] text-slate-400">Clique em uma contagem para ver os negócios.</p></div></div>
    <div v-else class="flex h-40 items-center justify-center text-xs text-slate-400">Sem dados para o período.</div>
    <div v-if="selectedItem" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/50 p-4" @click.self="selectedItem = null"><section class="flex max-h-[85vh] w-full max-w-3xl flex-col overflow-hidden rounded-2xl bg-white shadow-2xl dark:bg-slate-900"><header class="flex items-start justify-between gap-4 border-b border-slate-100 p-5 dark:border-slate-800"><div><p class="text-xs font-bold uppercase tracking-wide text-indigo-500">Detalhamento do relatório</p><h2 class="mt-1 text-lg font-bold text-slate-900 dark:text-white">Negócios {{ selectedItem.label.toLowerCase() }}</h2><p class="mt-1 text-xs text-slate-500 dark:text-slate-400">{{ selectedItem.businesses?.length || 0 }} negócio(s) no período selecionado.</p></div><button type="button" class="rounded-lg p-2 text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800" aria-label="Fechar detalhamento" @click="selectedItem = null"><span class="material-icons">close</span></button></header><div class="overflow-y-auto p-5"><div v-if="selectedItem.businesses?.length" class="space-y-3"><article v-for="business in selectedItem.businesses" :key="business.id" class="rounded-xl border border-slate-200 border-l-4 p-4 dark:border-slate-800" :style="{ borderLeftColor: business.product_color || '#6366f1' }"><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="font-bold text-slate-900 dark:text-white">{{ business.client_name }}</p><div class="mt-2 flex flex-wrap items-center gap-2 text-xs"><span class="inline-flex items-center gap-1.5 font-semibold text-slate-600 dark:text-slate-300"><i class="h-2 w-2 rounded-full" :style="{ backgroundColor: business.product_color || '#94a3b8' }" />{{ business.product_name }}</span><span class="rounded-md border px-2 py-1 font-semibold" :style="{ color: business.stage_color || '#64748b', borderColor: business.stage_color || '#cbd5e1' }">{{ business.stage_name }}</span></div></div><p class="font-bold text-indigo-600 dark:text-indigo-300">{{ formatCurrency(business.value || 0) }}</p></div><div class="mt-3 flex flex-wrap gap-x-5 gap-y-1 text-xs text-slate-500 dark:text-slate-400"><span>Responsável: {{ business.user_name }}</span><span>Data: {{ formatDate(business.created_at) }}</span><span v-if="business.loss_reason">Motivo: {{ business.loss_reason }}</span></div></article></div><div v-else class="rounded-xl border border-dashed border-slate-300 p-10 text-center text-sm text-slate-500 dark:border-slate-700 dark:text-slate-400">Nenhum negócio encontrado para este status.</div></div></section></div>
  </section>
</template>

<script setup lang="ts">
interface BusinessSummary { id: number, client_name?: string, product_name?: string, product_color?: string | null, user_name?: string, stage_name?: string, stage_color?: string | null, value?: number, created_at?: string | null, loss_reason?: string | null }
interface DonutItem { label: string, value: number, color: string, status?: number, businesses?: BusinessSummary[] }
const props = defineProps<{ title: string, subtitle?: string, items: DonutItem[], selectHandler?: (item: DonutItem) => void }>()
const selectedItem = ref<DonutItem | null>(null)
const handleSelect = (item: DonutItem) => { selectedItem.value = item; props.selectHandler?.(item) }
const formatCurrency = (value: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value)
const formatDate = (value?: string | null) => value ? new Intl.DateTimeFormat('pt-BR', { dateStyle: 'short' }).format(new Date(value)) : 'Data não informada'
const total = computed(() => props.items.reduce((sum, item) => sum + item.value, 0))
const donutStyle = computed(() => { let cursor = 0; const slices = props.items.map(item => { const start = cursor; cursor += (item.value / total.value) * 360; return `${item.color} ${start}deg ${cursor}deg` }); return { background: `conic-gradient(${slices.join(', ')})` } })
</script>
